#include <iostream>
#include <string>
#include <string_view>

class GeometricObject {
private:
    std::string color;
    bool filled;

public:
    GeometricObject() : color("white"), filled(false) {}

    GeometricObject(std::string_view c, bool f) : color(c), filled(f) {}

    std::string getColor() const {
        return color;
    }

    void setColor(std::string_view c) {
        color = c;
    }

    bool isFilled() const {
        return filled;
    }

    void setFilled(bool f) {
        filled = f;
    }

    std::string toString() const {
        return "GeometricObject [color: " + color + ", filled: " + (filled ? "true" : "false") + "]";
    }
};

int main() {
    GeometricObject shape1;
    std::cout << shape1.toString() << "\n";

    GeometricObject shape2("blue", true);
    std::cout << shape2.toString() << "\n";

    shape1.setColor("red");
    shape1.setFilled(true);
    std::cout << "Updated shape1 color: " << shape1.getColor() 
              << ", filled: " << std::boolalpha << shape1.isFilled() << "\n";
    return 0;
}

#include <iostream>
#include <string>
#include <string_view>

class GeometricObject {
private:
    std::string color;
    bool filled;

public:
    GeometricObject() : color("white"), filled(false) {}
    GeometricObject(std::string_view c, bool f) : color(c), filled(f) {}

    std::string getColor() const { return color; }
    void setColor(std::string_view c) { color = c; }
    bool isFilled() const { return filled; }
    void setFilled(bool f) { filled = f; }
};

class Circle : public GeometricObject {
private:
    double radius;

public:
    Circle() : radius(1.0) {}
    explicit Circle(double r) : radius(r >= 0 ? r : 0.0) {}
    Circle(double r, std::string_view c, bool f) : radius(r >= 0 ? r : 0.0) {
        setColor(c);      // Correct: invoking inherited public method
        setFilled(f);     // Correct: cannot write this->filled = f directly
    }

    double getRadius() const { return radius; }
    void setRadius(double r) { radius = (r >= 0) ? r : 0.0; }
    double getArea() const { return radius * radius * 3.14159; }
    double getPerimeter() const { return 2.0 * radius * 3.14159; }
};

int main() {
    Circle c(2.5, "red", true);
    std::cout << "Circle color: " << c.getColor() << "\n";
    std::cout << "Circle filled: " << std::boolalpha << c.isFilled() << "\n";
    std::cout << "Circle radius: " << c.getRadius() << "\n";
    std::cout << "Circle area: " << c.getArea() << "\n";
    return 0;
}
